func maskFirstTwo(ids []int) []int {
    head := ids[:2]
    head[0] = 0
    head[1] = 0
    return head
}

func main() {
    ids := []int{11, 12, 13, 14}
    masked := maskFirstTwo(ids)
    fmt.Println(ids, masked)
}

func upperAll(names []string) []string {
    out := make([]string, len(names))
    for _, n := range names {
        out = append(out, strings.ToUpper(n))
    }
    return out
}
